import os
from typing import List, Dict
import requests

def moderate_messages(messages: List[str]) -> List[Dict[str, object]]:
    """
    Moderate a batch of user messages using Azure AI Content Safety.

    Args:
        messages: List of user messages to moderate.

    Returns:
        List of per-message moderation decisions with details.
    """
    endpoint = os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = os.getenv("AZURE_CONTENT_SAFETY_KEY")
    if not endpoint or not key:
        raise ValueError("Azure Content Safety endpoint and key must be set in environment variables")

    url = f"{endpoint}/contentsafety/text:analyze?api-version=2023-10-01"
    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "application/json"
    }

    results = []
    for message in messages:
        payload = {
            "text": message,
            "categories": ["Hate", "SelfHarm", "Sexual", "Violence"],
            "outputType": "FourSeverityLevels"
        }

        response = requests.post(url, headers=headers, json=payload)
        response.raise_for_status()
        analysis_result = response.json()

        # Normalize the result to a decision
        decision = {
            "message": message,
            "blocked": any(
                category["severity"] >= 2
                for category in analysis_result.get("categoriesAnalysis", [])
            ),
            "categories": {
                category["category"]: {
                    "severity": category["severity"],
                    "blocked": category["severity"] >= 2
                }
                for category in analysis_result.get("categoriesAnalysis", [])
            },
            "provider": "azure_content_safety",
            "model": "text-moderation-latest"
        }
        results.append(decision)

    return results
